// Generated by Claude/specs/courses-tools/sync-hr.js from Claude/specs/lxd-course-hr-pilot/out-rounds/hr-pilot-block.js. Do not hand-edit.
(function(E){ const x = E["hr-m5"] = E["hr-m5"] || {units:{}}; x.units["hr-5-2"] = {"explain":{"id":"c-hr-5-2-e","course":"hr","unit":"hr-5-2","type":"explain","level":"B1","title":{"en":"Feedback that helps","tr":"Yardımcı olan geri bildirim","fa":"بازخوردی که کمک می‌کند"},"objective":{"en":"After this lesson, you can give feedback about a specific behaviour and its impact, not about the person.","tr":"Bu dersin sonunda kişiye değil, belirli bir davranışa ve onun etkisine dair geri bildirim verebileceksin.","fa":"بعد از این درس می‌توانی درباره‌ی یک رفتار مشخص و اثرش بازخورد بدهی، نه درباره‌ی خود آدم."},"hook":{"en":"Give feedback on one moment, not on the person, because people can only fix what they did. 'Careless' Deniz can only feel. 'On 14 July, the note was not signed' he can fix.","tr":"Kişiye değil, tek bir ana geri bildirim ver, çünkü insanlar yalnızca yaptıklarını düzeltebilir. 'Dikkatsiz' kelimesini Deniz yalnızca hissedebilir. 'On 14 July, the note was not signed' cümlesini ise düzeltebilir.","fa":"درباره‌ی یک لحظه بازخورد بده، نه درباره‌ی آدم، چون هر کسی فقط کاری را که کرده می‌تواند درست کند. کلمه‌ی «بی‌دقت» را دنیز فقط می‌تواند حس کند. ولی «On 14 July, the note was not signed» را می‌تواند درست کند."},"before":{"en":"Rewrite a label such as \"careless\" as feedback about one moment: when, what happened and what it caused.","tr":"\"Dikkatsiz\" gibi bir etiketi tek bir ana dair geri bildirime çevir: ne zaman, ne oldu ve neye yol açtı.","fa":"برچسبی مثل «بی‌دقت» را به بازخوردی درباره‌ی یک لحظه تبدیل کن: کی، چه اتفاقی افتاد و چه نتیجه‌ای داشت."},"rounds":[[1,4],[2,3]],"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"4"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"5"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"5"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Describe the moment, not the person","tr":"Kişiyi değil, anı anlat","fa":"آن لحظه را توصیف کن، نه آدم را"},"body":{"en":"Nobody can fix a word like \"lazy\". They can fix one action on one day. So say when, what happened and what it caused. Then ask how they see it.","tr":"Kimse \"tembel\" gibi bir kelimeyi düzeltemez. Ama bir günkü tek bir davranışı düzeltebilir. Bu yüzden ne zaman, ne olduğunu ve neye yol açtığını söyle. Sonra karşındakine nasıl gördüğünü sor.","fa":"هیچ‌کس نمی‌تواند کلمه‌ای مثل «تنبل» را درست کند. ولی می‌تواند یک کار در یک روز را درست کند. پس بگو کی، چه اتفاقی افتاد و چه نتیجه‌ای داشت. بعد بپرس نظر خودش چیست."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Feedback on events, not people: past simple + impact phrases","tr":"Kişiye değil olaya geri bildirim: past simple + etki ifadeleri","fa":"بازخورد درباره‌ی رفتار، نه آدم: گذشته‌ی ساده و عبارت‌های اثر"},"steps":[{"en":"Situation: one real moment, past simple with a time.","tr":"Durum: gerçek tek bir an, zamanla birlikte past simple.","fa":"موقعیت یعنی یک لحظه‌ی واقعی؛ با گذشته‌ی ساده و زمانش بگو.","ex":"On 14 July, at the Al Noor clinic, ..."},{"en":"Behaviour: what was done, not a label.","tr":"Davranış: ne yapıldığı, bir etiket değil.","fa":"رفتار یعنی کاری که انجام شد، نه یک برچسب.","ex":"...the delivery note was not signed."},{"en":"Impact: This meant that / The effect was that.","tr":"Etki: This meant that / The effect was that.","fa":"اثر را با This meant that یا The effect was that بگو.","ex":"This meant that we waited nine days for payment."}],"table":{"headers":{"en":["Part","Example"],"tr":["Parça","Örnek"],"fa":["بخش","مثال"]},"rows":[["Situation (when, where)","On 14 July, at the Al Noor clinic,"],["Behaviour (what was done, past simple)","the delivery note was not signed."],["Impact","This meant that we waited nine days for payment."],["Not this (a label)","You are careless with paperwork."]]},"tip":{"en":"Turkish and Persian feedback often comes as one adjective ('dikkatsiz', 'bi-deqqat'). That is quick, but in English workplaces it reads as a judgement of the person. Date + action + impact reads as fair.","tr":"Türkçede geri bildirim çoğu zaman tek bir sıfatla verilir: 'Dikkatsizsin.' İngilizce iş ortamında bu kişiye yönelik bir yargı gibi okunur. Tarih + eylem + etki adil okunur.","fa":"در فارسی بازخورد را اغلب با یک صفت می‌گوییم: «بی‌دقتی». این کوتاه است، ولی در محیط کار انگلیسی‌زبان قضاوت درباره‌ی خود آدم به حساب می‌آید. اگر تاریخ، کار و اثرش را بگویی، حرفت منصفانه به نظر می‌رسد."},"wrong":"You are careless.","right":"On 14 July, the delivery note was not signed."},{"eyebrow":{"en":"Key phrases","tr":"Anahtar ifadeler","fa":"عبارت‌های کلیدی"},"head":{"en":"Phrases for this task","tr":"Bu görev için ifadeler","fa":"عبارت‌های این کار"},"phrases":[{"phrase":"On (date), when..., you...","meaning":{"en":"Sets the situation and behaviour.","tr":"Durumu ve davranışı belirtir.","fa":"موقعیت و رفتار را مشخص می‌کند."}},{"phrase":"The effect was that...","meaning":{"en":"States the impact.","tr":"Etkiyi söyler.","fa":"اثر را می‌گوید."}},{"phrase":"How do you see it?","meaning":{"en":"Invites the other person's view.","tr":"Karşı tarafın görüşünü ister.","fa":"نظر طرف مقابل را جویا می‌شود."}},{"phrase":"behaviour","meaning":{"en":"What someone does that others can see.","tr":"davranış.","fa":"رفتار (کاری که دیگران می‌بینند)"}},{"phrase":"impact","meaning":{"en":"The effect something has.","tr":"etki.","fa":"اثر؛ پیامد"}}]},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Clear, not harsh","tr":"Net ama sert değil","fa":"روشن، نه تند"},"body":{"en":"Cultures differ in how directly they give negative feedback. Some managers, for example in the Netherlands, say it very plainly; many British managers soften it so much (\"just a few small things you might consider\") that the message is missed. Specific feedback about one moment works across cultures because it is clear without being harsh.","tr":"Kültürler olumsuz geri bildirimi ne kadar doğrudan verdikleri konusunda farklıdır. Bazı yöneticiler, örneğin Hollanda'da, bunu çok açık söyler; birçok İngiliz yönetici ise o kadar yumuşatır ki (\"just a few small things you might consider\") mesaj kaybolur. Tek bir an hakkındaki somut geri bildirim kültürler arasında işe yarar, çünkü sert olmadan açıktır.","fa":"فرهنگ‌ها در صراحتِ بازخورد منفی با هم فرق دارند. بعضی مدیران، مثلاً در هلند، آن را خیلی بی‌پرده می‌گویند؛ در مقابل، خیلی از مدیران بریتانیایی آن‌قدر آن را نرم می‌کنند («just a few small things you might consider») که پیام اصلاً به گوش نمی‌رسد. ما ایرانی‌ها هم گاهی با تعارف همین کار را می‌کنیم. بازخورد مشخص درباره‌ی یک لحظه در همه‌ی فرهنگ‌ها جواب می‌دهد، چون روشن است بی‌آنکه تند باشد."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From weak to strong","tr":"Zayıftan güçlüye","fa":"از برچسب تا لحظه و کار و اثر"},"text":"Facts: In Monday's meeting they interrupted a colleague twice. She then stopped sharing ideas.","item":"You are not a team player.","why":{"en":"Weak: a label, and nothing to act on. Strong: moment, action, effect.","tr":"Zayıf: bir etiket; üzerinde çalışılacak bir şey yok. Güçlü: an, davranış, etki.","fa":"نسخه‌ی اول یک برچسب است و نمی‌گوید چه کار باید کرد. نسخه‌ی دوم لحظه، کار و اثرش را می‌گوید."},"answer":"In Monday's meeting, you interrupted a colleague twice. She stopped sharing her ideas.","cut":["not a team player"],"cutHint":{"en":"Tap the label: nobody can fix it.","tr":"Etikete dokun: Onu kimse düzeltemez.","fa":"روی برچسب بزن: هیچ‌کس نمی‌تواند درستش کند."}},"quick":{"prompt":"A British manager says: \"Just a few small things you might consider about your reports.\" What is the risk?","options":["The message is softened so much that it is missed","It is too harsh","It is against the law"],"correct":0,"why":{"en":"The message may be missed: some managers soften it so much that the problem never lands. Feedback about one moment is clear without being harsh.","tr":"Mesaj gözden kaçabilir: Bazı yöneticiler eleştiriyi o kadar yumuşatır ki sorun hiç anlaşılmaz. Tek bir ana dair geri bildirim sert olmadan nettir.","fa":"ممکن است پیام گم شود: بعضی مدیرها حرفشان را آن‌قدر نرم می‌کنند که مشکل اصلاً فهمیده نمی‌شود. بازخورد درباره‌ی یک لحظه‌ی مشخص روشن است، بدون اینکه تند باشد."},"point":4},"remember":{"en":"Could the person repeat the same behaviour tomorrow on purpose? Then it is a behaviour. If not (careless, rude), it is a label. Result of this lesson: you can give fair feedback on behaviour. You also have three labels rewritten as feedback.","tr":"Kişi aynı davranışı yarın bilerek tekrar edebilir mi? O zaman bu bir davranıştır. Edemiyorsa (careless, rude) bir etikettir. Bu dersin sonucu: davranış üzerine adil geri bildirim verebilirsin ve elinde geri bildirime çevrilmiş üç etiket olur.","fa":"آیا آن فرد می‌تواند فردا همین رفتار را عمداً تکرار کند؟ پس رفتار است. اگر نه (careless، rude)، برچسب است. حالا می‌توانی درباره‌ی رفتار بازخورد منصفانه بدهی. سه برچسب را هم به بازخورد تبدیل کرده‌ای."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Showing impact with the third conditional","tr":"Etkiyi third conditional ile göstermek","fa":"نشان دادن اثر با شرطی نوع سوم"},"steps":[{"en":"If + had + past participle.","tr":"If + had + past participle.","fa":"در بخش if، had و اسم مفعول می‌آید.","ex":"If the note had been signed, ..."},{"en":"Result: would have + past participle.","tr":"Sonuç: would have + past participle.","fa":"در بخش نتیجه، would have و اسم مفعول می‌آید.","ex":"...the clinic would have paid on time."},{"en":"Then look forward: From now on, could you...?","tr":"Sonra ileriye bak: From now on, could you...?","fa":"بعد به آینده نگاه کن: From now on, could you...?","ex":"From now on, could you get every note signed?"}],"table":{"headers":{"en":["If-part","Result","Forward"],"tr":["If kısmı","Sonuç","İleriye"],"fa":["بخش if","نتیجه","رو به آینده"]},"rows":[["If the note had been signed,","the clinic would have paid on time.","From now on, could you check every note?"],["If you had called earlier,","we would have kept the client.","Next time, please call first."]]},"body":{"en":"B2 track: in your development feedback, add one third-conditional sentence about impact, followed by \"From now on, could you...?\"","tr":"B2 yolu: gelişim geri bildirimine etki hakkında bir third conditional cümlesi ekle ve ardından \"From now on, could you...?\" de.","fa":"مسیر B2: به بازخورد پیشرفتت یک جمله‌ی شرطی نوع سوم درباره‌ی اثر اضافه کن و بعدش بگو «⁨From now on, could you...?⁩»."}},"source":{"en":"Informed by the Situation-Behavior-Impact feedback model (Center for Creative Leadership).","tr":"Durum-Davranış-Etki geri bildirim modelinden (Center for Creative Leadership) yararlanır.","fa":"با استفاده از الگوی بازخورد «موقعیت، رفتار، اثر» (Center for Creative Leadership)."}},"grammar":{"id":"c-hr-5-2-g","level":"B1","course":"hr","unit":"hr-5-2","title":"Feedback on events, not people: past simple + impact phrases","titleTr":"Kişiye değil olaya geri bildirim: past simple + etki ifadeleri","exp":{"en":"Helpful feedback describes one real moment, so it uses the past simple with a time: \"On 14 July, the delivery note at the clinic was not signed.\" Compare \"You are careless\" (present simple + adjective): that is a label about the person, and nobody knows what to change. After the event, name the impact with a short phrase: \"This meant that the clinic could not confirm the delivery.\", \"The effect was that we waited nine days for payment.\" Mean is irregular: mean, meant, meant (never \"meaned\"). Use the same pattern for praise: \"On 2 August, you called the client before they called us. The effect was that they renewed for a year.\"","tr":"Yararlı geri bildirim gerçek bir anı anlatır, bu yüzden bir zaman ifadesiyle past simple kullanır: \"On 14 July, the delivery note at the clinic was not signed.\" Bunu \"You are careless\" ile karşılaştır (present simple + sıfat): bu kişi hakkında bir etikettir ve kimse neyi değiştireceğini bilmez. Olaydan sonra etkiyi kısa bir ifadeyle söyle: \"This meant that the clinic could not confirm the delivery.\", \"The effect was that we waited nine days for payment.\" Mean düzensizdir: mean, meant, meant (asla \"meaned\"). Övgü için de aynı kalıbı kullan: \"On 2 August, you called the client before they called us. The effect was that they renewed for a year.\"","fa":"بازخورد مفید یک لحظه‌ی واقعی را توصیف می‌کند؛ پس با گذشته‌ی ساده و همراه با زمانِ مشخص گفته می‌شود: «⁨On 14 July, the delivery note at the clinic was not signed.⁩» این را با «You are careless» (حال ساده + صفت) مقایسه کن: آن جمله برچسبی است که به خود آدم زده می‌شود و هیچ‌کس نمی‌فهمد دقیقاً چه چیزی را باید تغییر دهد. بعد از گفتن رویداد، اثرش را با یک عبارت کوتاه بگو: «⁨This meant that the clinic could not confirm the delivery.⁩» یا «⁨The effect was that we waited nine days for payment.⁩» فعل mean بی‌قاعده است: mean، meant، meant (هرگز «meaned»). برای تعریف و تشویق هم همین الگو را به کار ببر: «⁨On 2 August, you called the client before they called us. The effect was that they renewed for a year.⁩»"},"formsTable":{"headers":{"en":["Part","Example"],"tr":["Parça","Örnek"],"fa":["بخش","مثال"]},"rows":[["Situation (when, where)","On 14 July, at the Al Noor clinic,"],["Behaviour (what was done, past simple)","the delivery note was not signed."],["Impact","This meant that we waited nine days for payment."],["Not this (a label)","You are careless with paperwork."]]},"wrong":"You are always careless with paperwork.","right":"On 14 July, the delivery note at the clinic was not signed.","blank":{"sentence":"On Monday, the delivery note ___ not signed.","word":"was","distractors":["is","has"]},"wrong2":"This meaned that we waited nine days for payment.","right2":"This meant that we waited nine days for payment.","blank2":{"sentence":"This ___ that the clinic could not confirm the delivery.","word":"meant","distractors":["mean","meaning"]},"expParts":{"hook":{"en":"'Careless' Deniz can only feel. 'On 14 July, the note was not signed' he can fix.","tr":"'Dikkatsiz' kelimesini Deniz yalnızca hissedebilir. 'On 14 July, the note was not signed' cümlesini ise düzeltebilir.","fa":"کلمه‌ی «بی‌دقت» را دنیز فقط می‌تواند حس کند. ولی «On 14 July, the note was not signed» را می‌تواند درست کند."},"tryWhy":{"en":"meant: mean is irregular. mean, meant, meant; 'meaned' does not exist.","tr":"meant: mean düzensizdir: mean, meant, meant. 'meaned' diye bir şey yok.","fa":"جواب meant است: فعل mean بی‌قاعده است: mean، meant، meant. meaned وجود ندارد."},"rule":[{"en":"Situation: one real moment, past simple with a time.","tr":"Durum: gerçek tek bir an, zamanla birlikte past simple.","fa":"موقعیت یعنی یک لحظه‌ی واقعی؛ با گذشته‌ی ساده و زمانش بگو.","ex":"On 14 July, at the Al Noor clinic, ..."},{"en":"Behaviour: what was done, not a label.","tr":"Davranış: ne yapıldığı, bir etiket değil.","fa":"رفتار یعنی کاری که انجام شد، نه یک برچسب.","ex":"...the delivery note was not signed."},{"en":"Impact: This meant that / The effect was that.","tr":"Etki: This meant that / The effect was that.","fa":"اثر را با This meant that یا The effect was that بگو.","ex":"This meant that we waited nine days for payment."}],"test":{"en":"Could the person repeat the same behaviour tomorrow on purpose? Then it is a behaviour. If not (careless, rude), it is a label.","tr":"Kişi aynı davranışı yarın bilerek tekrar edebilir mi? O zaman bu bir davranıştır. Edemiyorsa (careless, rude) bir etikettir.","fa":"آیا آن فرد می‌تواند فردا همین رفتار را عمداً تکرار کند؟ پس رفتار است. اگر نه (careless، rude)، برچسب است."},"contrast":{"en":"Turkish and Persian feedback often comes as one adjective ('dikkatsiz', 'bi-deqqat'). That is quick, but in English workplaces it reads as a judgement of the person. Date + action + impact reads as fair.","tr":"Türkçede geri bildirim çoğu zaman tek bir sıfatla verilir: 'Dikkatsizsin.' İngilizce iş ortamında bu kişiye yönelik bir yargı gibi okunur. Tarih + eylem + etki adil okunur.","fa":"در فارسی بازخورد را اغلب با یک صفت می‌گوییم: «بی‌دقتی». این کوتاه است، ولی در محیط کار انگلیسی‌زبان قضاوت درباره‌ی خود آدم به حساب می‌آید. اگر تاریخ، کار و اثرش را بگویی، حرفت منصفانه به نظر می‌رسد."}},"errorWatch":[{"find":["meaned","this mean that","the effect is that we waited"],"fix":{"en":"Use the past: 'This meant that...', 'The effect was that...'","tr":"Geçmiş zaman kullan: 'This meant that...', 'The effect was that...'","fa":"زمان گذشته بیاور: «⁨This meant that...⁩» و «⁨The effect was that...⁩»"}},{"find":["you are careless","you're careless","you are rude","you're rude","you are lazy","you're lazy","needs to try harder","always careless"],"fix":{"en":"This is a label. Describe one moment instead: date, what happened, the effect.","tr":"Bu bir etiket. Onun yerine tek bir anı anlat: tarih, ne oldu, etkisi.","fa":"این یک برچسب است. به‌جایش یک لحظه را توصیف کن: تاریخ، چه اتفاقی افتاد و اثرش."}}]},"b2":{"id":"c-hr-5-2-b2","level":"B2","track":"B2","course":"hr","unit":"hr-5-2","title":"Showing impact with the third conditional","titleTr":"Etkiyi third conditional ile göstermek","exp":{"en":"Sometimes the clearest way to show impact is to describe what would have happened: \"If the note had been signed, the clinic would have paid on time.\" This is the third conditional: If + had + past participle, then would have + past participle. It talks about an unreal past, so use it to explain impact, not to blame, and follow it with a forward-looking line: \"From now on, could you...?\" Form traps: no would in the if-part (\"If the note would have been signed\" is wrong), and keep the past participle after would have (\"would have kept\", not \"would have keep\").","tr":"Bazen etkiyi göstermenin en açık yolu ne olacağını anlatmaktır: \"If the note had been signed, the clinic would have paid on time.\" Bu third conditional'dır: If + had + past participle, ardından would have + past participle. Gerçek olmayan bir geçmişten bahseder; Türkçedeki \"imzalanmış olsaydı, zamanında ödenmiş olurdu\" yapısına benzer. Suçlamak için değil, etkiyi açıklamak için kullan ve ardından ileriye bakan bir cümle ekle: \"From now on, could you...?\" Biçim tuzakları: if'li kısımda would yok (\"If the note would have been signed\" yanlış) ve would have'dan sonra past participle'ı koru (\"would have kept\", \"would have keep\" değil).","fa":"گاهی روشن‌ترین راه برای نشان دادن اثر یک رفتار این است که بگویی «چه می‌شد اگر...»: «⁨If the note had been signed, the clinic would have paid on time.⁩» این شرطی نوع سوم است: if + had + اسم مفعول و بعد would have + اسم مفعول؛ یعنی «اگر رسید امضا شده بود، درمانگاه به‌موقع پرداخت می‌کرد». چون از گذشته‌ای حرف می‌زند که دیگر قابل تغییر نیست، از آن برای توضیح اثر استفاده کن، نه برای سرزنش، و بلافاصله یک جمله‌ی رو به آینده بیاور: «⁨From now on, could you...?⁩» دو تله‌ی ساختاری: در بخش if، would نمی‌آید («If the note would have been signed» غلط است)، و بعد از would have اسم مفعول می‌آید («would have kept»، نه «would have keep»)."},"formsTable":{"headers":{"en":["If-part","Result","Forward"],"tr":["If kısmı","Sonuç","İleriye"],"fa":["بخش if","نتیجه","رو به آینده"]},"rows":[["If the note had been signed,","the clinic would have paid on time.","From now on, could you check every note?"],["If you had called earlier,","we would have kept the client.","Next time, please call first."]]},"wrong":"If the note would have been signed, the clinic would have paid on time.","right":"If the note had been signed, the clinic would have paid on time.","blank":{"sentence":"If the note ___ signed, the clinic would have paid on time.","word":"had been","distractors":["was","would be"]},"wrong2":"If you had called earlier, we would have keep the client.","right2":"If you had called earlier, we would have kept the client.","blank2":{"sentence":"If you had called earlier, we ___ the client.","word":"would have kept","distractors":["would kept","had kept"]},"useIn":{"en":"B2 track: in your development feedback, add one third-conditional sentence about impact, followed by \"From now on, could you...?\"","tr":"B2 yolu: gelişim geri bildirimine etki hakkında bir third conditional cümlesi ekle ve ardından \"From now on, could you...?\" de.","fa":"مسیر B2: به بازخورد پیشرفتت یک جمله‌ی شرطی نوع سوم درباره‌ی اثر اضافه کن و بعدش بگو «⁨From now on, could you...?⁩»."},"exitItem":{"from":"hr-5-2","kind":"blank","prompt":"If you ___ the client, they would not have complained.","options":["called","had called","would call"],"correct":1,"why":{"en":"had called: an unreal past takes if + past perfect, then would have + past participle. 'Called' and 'would call' don't go back far enough.","tr":"had called: gerçekleşmemiş geçmiş if + past perfect, sonra would have + üçüncü hâl alır. 'Called' ve 'would call' yeterince geriye gitmez.","fa":"had called درست است، چون برای گذشته‌ی غیرواقعی بعد از if گذشته‌ی کامل می‌آید و بعد would have. called و would call به اندازه‌ی کافی به گذشته برنمی‌گردند."}},"expParts":{"hook":{"en":"'If the note had been signed, the clinic would have paid on time.' The impact, shown without blame.","tr":"'If the note had been signed, the clinic would have paid on time.' Suçlamadan gösterilen bir etki.","fa":"«⁨If the note had been signed, the clinic would have paid on time.⁩» اثر کار، بدون سرزنش."},"tryWhy":{"en":"would have kept: after would have comes the past participle (kept). would kept and had kept are wrong here.","tr":"would have kept: would have'den sonra past participle (kept) gelir.","fa":"جواب would have kept است: بعد از would have اسم مفعول (kept) می‌آید."},"rule":[{"en":"If + had + past participle.","tr":"If + had + past participle.","fa":"در بخش if، had و اسم مفعول می‌آید.","ex":"If the note had been signed, ..."},{"en":"Result: would have + past participle.","tr":"Sonuç: would have + past participle.","fa":"در بخش نتیجه، would have و اسم مفعول می‌آید.","ex":"...the clinic would have paid on time."},{"en":"Then look forward: From now on, could you...?","tr":"Sonra ileriye bak: From now on, could you...?","fa":"بعد به آینده نگاه کن: From now on, could you...?","ex":"From now on, could you get every note signed?"}],"test":{"en":"Is there would in the if-part? Swap it for had.","tr":"if kısmında would var mı? Onu had ile değiştir.","fa":"در بخش if کلمه‌ی would هست؟ به‌جایش had بگذار."},"contrast":{"en":"Persian 'agar emza shode bud, pul ra be-mowqe midad' uses a past form in both halves. English uses had in the if-part and would have in the result.","tr":"Türkçede 'Not imzalansaydı klinik zamanında öderdi' deriz. İngilizcede if kısmı had + past participle, sonuç kısmı would have + past participle ile kurulur.","fa":"در فارسی می‌گوییم «اگر رسید امضا شده بود، درمانگاه به‌موقع پرداخت می‌کرد». در انگلیسی بخش if با had و بخش نتیجه با would have ساخته می‌شود."}},"errorWatch":[{"find":["if the note would have","if you would have","if he would have","would have keep","would have pay","would kept"],"fix":{"en":"If + had + past participle, would have + past participle: 'If the note had been signed, the clinic would have paid on time.'","tr":"if kısmında had + üçüncü hâl, sonuç kısmında would have + üçüncü hâl: 'If the note had been signed, the clinic would have paid on time.'","fa":"در بخش if، had و اسم مفعول می‌آید و در بخش نتیجه would have و اسم مفعول: «If the note had been signed, the clinic would have paid on time.»"}}]},"vocab":{"id":"c-hr-5-2-v","level":"B1","category":"vocab","course":"hr","unit":"hr-5-2","goals":["career"],"title":{"en":"Feedback","tr":"Geri Bildirim","fa":"بازخورد"},"cards":[{"word":"constructive","sentence":"Constructive feedback helps people improve.","meaning":{"en":"Helpful and meant to improve something.","tr":"yapıcı.","fa":"سازنده (با هدف بهتر کردن)"}},{"word":"judgemental","sentence":"\"Careless\" sounds judgemental.","meaning":{"en":"Judging a person too quickly or harshly.","tr":"yargılayıcı.","fa":"قضاوت‌گرانه؛ با پیش‌داوری تند"}},{"word":"behaviour","sentence":"Give feedback on behaviour, not personality.","meaning":{"en":"What someone does that others can see.","tr":"davranış.","fa":"رفتار (کاری که دیگران می‌بینند)"}},{"word":"impact","sentence":"Explain the impact on the client.","meaning":{"en":"The effect something has.","tr":"etki.","fa":"اثر؛ پیامد"}},{"word":"praise","sentence":"Specific praise tells people what to repeat.","meaning":{"en":"Words that show you think someone did well.","tr":"övgü.","fa":"تحسین؛ تعریف و تمجید"}},{"word":"criticism","sentence":"He took the criticism well.","meaning":{"en":"Words that point out what is wrong.","tr":"eleştiri.","fa":"انتقاد"}},{"word":"act on","sentence":"Would you act on feedback like that?","meaning":{"en":"To do something because of advice or information.","tr":"... doğrultusunda harekete geçmek.","fa":"بر اساس توصیه یا اطلاعاتی اقدام کردن"}},{"word":"observation","sentence":"Start with an observation, not an opinion.","meaning":{"en":"Something you saw or noticed.","tr":"gözlem.","fa":"مشاهده (چیزی که دیده یا متوجه شده‌ای)"}},{"word":"delivery note","sentence":"The customer signs the delivery note.","meaning":{"en":"A paper that shows goods were delivered.","tr":"irsaliye, teslim belgesi.","fa":"رسید تحویل کالا (برگه‌ای که نشان می‌دهد کالا تحویل شده)"}},{"word":"confirm receipt","sentence":"The clinic could not confirm receipt.","meaning":{"en":"To say officially that something arrived.","tr":"teslim alındığını teyit etmek.","fa":"دریافت چیزی را رسماً تأیید کردن"}}]},"story":{"id":"c-hr-5-2-s","level":"B1","genre":"Workplace","course":"hr","unit":"hr-5-2","title":{"en":"The Word \"Careless\"","tr":"\"Dikkatsiz\" Sözcüğü","fa":"کلمه‌ی «بی‌دقت»"},"text":"Omar's draft of Deniz's mid-year feedback was one line long: \"Careless with paperwork. Needs to try harder.\"\n\n\"It's true,\" he said on the call. \"Ask accounts.\"\n\nLeyla had asked accounts. On 14 July the delivery note at the Al Noor clinic was not signed, and the clinic could not confirm the delivery. Atlas waited nine days for the payment. It had happened twice.\n\n\"I believe you,\" she said. \"But what will Deniz do differently on Monday after he reads 'careless'?\"\n\nOmar opened his mouth and closed it.\n\nShe wrote it again while he watched. \"On 14 July, at the Al Noor clinic, the delivery note was not signed. This meant that the clinic could not confirm the delivery, and we waited nine days for payment.\"\n\n\"That's longer,\" said Omar.\n\n\"It's longer. But he can fix it. 'Careless' he can only feel.\"\n\nOmar was quiet for a second. Then, to her surprise, he added a line himself. \"On 2 August, when your van broke down, you called the client before they called us. The effect was that they renewed their contract for another year.\"\n\n\"You noticed that?\" Leyla asked.\n\n\"I notice everything,\" said Omar. \"I just don't write it down.\"\n\nDeniz read the feedback that evening. He read the second paragraph three times. The next morning he bought a clipboard with a pen on a string, and he did not let a single customer go without signing. Nobody told him to buy it.","vocab":[{"word":"draft","en":"A first version of a text.","tr":"taslak","fa":"پیش‌نویس"},{"word":"accounts","en":"The team that handles money and payments.","tr":"muhasebe","fa":"واحد حسابداری و مالی"},{"word":"renew a contract","en":"To continue an agreement for another period.","tr":"sözleşmeyi yenilemek","fa":"تمدید کردن قرارداد"},{"word":"clipboard","en":"A board that holds papers while you write.","tr":"kıskaçlı not altlığı (clipboard)","fa":"تخته‌شاسی؛ کلیپ‌بورد"},{"word":"string","en":"A thin rope.","tr":"ip","fa":"نخ"}],"quiz":[{"prompt":"Why was \"careless with paperwork\" not helpful?","options":["It was untrue","Deniz could not know what to do differently","It was too long"],"correct":1},{"prompt":"Choose the correct sentence.","options":["This meaned that we waited nine days.","This mean that we waited nine days.","This meant that we waited nine days."],"correct":2},{"prompt":"What did Omar add to the feedback?","options":["A specific example of something Deniz did well","A written warning","A new goal"],"correct":0},{"prompt":"Why did Deniz read the second paragraph three times?","options":["He did not understand it","He was surprised and pleased that his good action had been noticed","It had a mistake in it"],"correct":1}],"notice":{"en":"Omar's feedback is one word long: careless. Watch what Leyla asks him, and what Omar writes next without being asked.","tr":"Omar'ın geri bildirimi tek kelime: dikkatsiz. Leyla'nın ona ne sorduğuna ve Omar'ın sonra kimse istemeden ne yazdığına dikkat et.","fa":"بازخورد عمر یک کلمه است: بی‌دقت. دقت کن لیلا از او چه می‌پرسد و عمر بعد، بی‌آنکه کسی بخواهد، چه می‌نویسد."},"bridge":{"en":"'On 14 July... This meant that...' Next: see how feedback on events is built.","tr":"'On 14 July... This meant that...' Sırada: olaylar üzerine geri bildirimin nasıl kurulduğunu gör.","fa":"«⁨On 14 July... This meant that...⁩» قدم بعد: ببین بازخورد درباره‌ی رویداد چطور ساخته می‌شود."}},"speaking":{"id":"hr-5-2","course":"hr","unit":"hr-5-2","topic":{"en":"Giving Specific Feedback","tr":"Somut Geri Bildirim Vermek","fa":"دادن بازخورد مشخص"},"warmup":{"en":"What is the most useful piece of feedback you ever got? Why was it useful?","tr":"Aldığın en yararlı geri bildirim neydi? Neden yararlıydı?","fa":"مفیدترین بازخوردی که تا حالا گرفته‌ای چه بوده است؟ چرا به کارت آمد؟"},"questions":[{"en":"Give Deniz one piece of positive feedback: situation, behaviour, impact.","tr":"Deniz'e bir olumlu geri bildirim ver: durum, davranış, etki.","fa":"یک بازخورد مثبت به دنیز بده: موقعیت، رفتار، اثر."},{"en":"Give one piece of development feedback in the same shape, without labels.","tr":"Aynı yapıda, etiket kullanmadan bir gelişim geri bildirimi ver.","fa":"یک بازخورد برای پیشرفت، با همین ساختار و بدون برچسب، به او بده."},{"en":"Ask for his view: \"How do you see it?\" Then agree one action.","tr":"Görüşünü sor: \"How do you see it?\" Sonra bir eylem üzerinde anlaşın.","fa":"نظرش را بپرس: «⁨How do you see it?⁩» بعد سر یک اقدام مشخص با او توافق کن."}],"followups":[{"en":"Give both pieces of feedback in 90 seconds, then 60, then 45.","tr":"İki geri bildirimi 90, sonra 60, sonra 45 saniyede ver.","fa":"هر دو بازخورد را یک بار در ۹۰ ثانیه، بعد در ۶۰ و بعد در ۴۵ ثانیه بگو."},{"en":"Now give a colleague one piece of feedback about one real event: what happened, and the effect.","tr":"Şimdi bir iş arkadaşına gerçek bir olay hakkında geri bildirim ver: ne oldu ve etkisi ne oldu.","fa":"حالا درباره‌ی یک اتفاق واقعی به همکارت بازخورد بده: چه شد و چه اثری داشت."}],"expressions":[{"phrase":"On (date), when..., you...","meaning":{"en":"Sets the situation and behaviour.","tr":"Durumu ve davranışı belirtir.","fa":"موقعیت و رفتار را مشخص می‌کند."}},{"phrase":"The effect was that...","meaning":{"en":"States the impact.","tr":"Etkiyi söyler.","fa":"اثر را می‌گوید."}},{"phrase":"How do you see it?","meaning":{"en":"Invites the other person's view.","tr":"Karşı tarafın görüşünü ister.","fa":"نظر طرف مقابل را جویا می‌شود."}}],"culture":{"en":"Cultures differ in how directly they give negative feedback. Some managers, for example in the Netherlands, say it very plainly; many British managers soften it so much (\"just a few small things you might consider\") that the message is missed. Specific feedback about one moment works across cultures because it is clear without being harsh.","tr":"Kültürler olumsuz geri bildirimi ne kadar doğrudan verdikleri konusunda farklıdır. Bazı yöneticiler, örneğin Hollanda'da, bunu çok açık söyler; birçok İngiliz yönetici ise o kadar yumuşatır ki (\"just a few small things you might consider\") mesaj kaybolur. Tek bir an hakkındaki somut geri bildirim kültürler arasında işe yarar, çünkü sert olmadan açıktır.","fa":"فرهنگ‌ها در صراحتِ بازخورد منفی با هم فرق دارند. بعضی مدیران، مثلاً در هلند، آن را خیلی بی‌پرده می‌گویند؛ در مقابل، خیلی از مدیران بریتانیایی آن‌قدر آن را نرم می‌کنند («just a few small things you might consider») که پیام اصلاً به گوش نمی‌رسد. ما ایرانی‌ها هم گاهی با تعارف همین کار را می‌کنیم. بازخورد مشخص درباره‌ی یک لحظه در همه‌ی فرهنگ‌ها جواب می‌دهد، چون روشن است بی‌آنکه تند باشد."},"model":"Deniz, I have two pieces of feedback. First, on 2 August, when your van broke down, you called the client before they called us. The effect was that they renewed their contract. Thank you. Second, on 14 July, the delivery note at the Al Noor clinic was not signed. This meant that we waited nine days for payment. How do you see it?","selfCheck":[{"en":"Each piece had a situation, a behaviour and an impact.","tr":"Her geri bildirimde durum, davranış ve etki vardı.","fa":"هر بازخورد موقعیت، رفتار و اثر داشت."},{"en":"I used the past simple with a date or time.","tr":"Tarih ya da zamanla past simple kullandım.","fa":"از گذشته‌ی ساده همراه با تاریخ یا زمان استفاده کردم."},{"en":"I used no labels such as careless or rude.","tr":"careless ya da rude gibi etiketler kullanmadım.","fa":"هیچ برچسبی مثل careless یا rude به کار نبردم."},{"en":"I asked 'How do you see it?' and agreed one action.","tr":"'How do you see it?' diye sordum ve bir eylem üzerinde anlaştık.","fa":"پرسیدم «⁨How do you see it?⁩» و روی یک اقدام توافق کردیم."}]},"judge":{"id":"c-hr-5-2-j","course":"hr","unit":"hr-5-2","type":"judge","parts":["Situation","Behaviour","Impact"],"instruction":{"en":"Read each piece of feedback. Tap the parts you can find: situation, behaviour, impact. The best feedback has all three.","tr":"Her geri bildirimi oku. Bulabildiğin parçalara dokun: durum, davranış, etki. En iyi geri bildirimde üçü de vardır.","fa":"هر بازخورد را بخوان و بخش‌هایی را که در آن هست لمس کن: موقعیت، رفتار، اثر. بهترین بازخورد هر سه را دارد."},"items":[{"answer":"You are careless with paperwork.","present":[],"fix":{"en":"A label, not feedback: no moment, no behaviour to change, no impact. Try: \"On 14 July, the delivery note at the clinic was not signed...\"","tr":"Bu bir etiket, geri bildirim değil: an yok, değiştirilecek davranış yok, etki yok. Şunu dene: \"On 14 July, the delivery note at the clinic was not signed...\"","fa":"این یک برچسب است، نه بازخورد: نه لحظه‌ی مشخصی دارد، نه رفتاری که بشود تغییرش داد، نه اثری. مثلاً این‌طور بگو: «⁨On 14 July, the delivery note at the clinic was not signed...⁩»"}},{"answer":"On 14 July, the delivery note at the Al Noor clinic was not signed, so we waited nine days for payment.","present":["Situation","Behaviour","Impact"],"fix":null},{"answer":"In yesterday's meeting, you interrupted Selin three times.","present":["Situation","Behaviour"],"fix":{"en":"Clear, but no impact. Add: \"The effect was that she stopped sharing her ideas.\"","tr":"Açık, ama etki yok. Ekle: \"The effect was that she stopped sharing her ideas.\"","fa":"روشن است، اما اثرش را نگفته. اضافه کن: «⁨The effect was that she stopped sharing her ideas.⁩»"}},{"answer":"Your attitude is really negative and it affects the whole team.","present":["Impact"],"fix":{"en":"No moment and no behaviour anyone can see; \"attitude\" is a judgement. Name one situation and what the person did.","tr":"An yok ve kimsenin görebileceği bir davranış yok; \"attitude\" bir yargıdır. Bir durumu ve kişinin ne yaptığını söyle.","fa":"نه لحظه‌ی مشخصی دارد و نه رفتاری که دیده شود؛ attitude خودش یک قضاوت است. یک موقعیت مشخص و کاری را که آن فرد کرد بگو."}},{"answer":"Great job last week!","present":["Situation"],"fix":{"en":"Kind, but nobody can repeat it. Say what exactly was great and why it mattered.","tr":"Nazik, ama kimse bunu tekrarlayamaz. Tam olarak neyin harika olduğunu ve neden önemli olduğunu söyle.","fa":"مهربانانه است، اما کسی نمی‌تواند تکرارش کند. دقیقاً بگو چه چیزی عالی بود و چرا اهمیت داشت."}}]},"writing":{"id":"c-hr-5-2-w","title":{"en":"Feedback without labels","tr":"Etiketsiz geri bildirim","fa":"بازخورد بدون برچسب"},"course":"hr","unit":"hr-5-2","type":"writing","difficulty":"medium","prompt":{"en":"Rewrite these three comments as specific feedback (situation, behaviour, impact), inventing realistic details (60-90 words): 1. You're careless with paperwork. 2. You're rude to customers. 3. Great job last week!","tr":"Bu üç yorumu gerçekçi ayrıntılar uydurarak somut geri bildirim olarak yeniden yaz (durum, davranış, etki) (60-90 kelime): 1. You're careless with paperwork. 2. You're rude to customers. 3. Great job last week!","fa":"این سه جمله را به بازخورد مشخص (موقعیت، رفتار، اثر) تبدیل کن و برایشان جزئیات واقع‌گرایانه بساز (۶۰ تا ۹۰ کلمه): 1. You're careless with paperwork. 2. You're rude to customers. 3. Great job last week!"},"model":"1. On 14 July, at the Al Noor clinic, the delivery note was not signed. This meant that we waited nine days for payment. 2. On Tuesday, when the pharmacy manager asked about the delay, you said \"Not my problem\" and walked away. The effect was that she called Omar to complain. 3. On 2 August, when your van broke down, you called the client before they called us. The effect was that they renewed their contract.","frame":"1. On ___, at ___, ___. This meant that ___. 2. On ___, when ___, you ___. The effect was that ___. 3. On ___, when ___, you ___. The effect was that ___.","words":[{"word":"on"},{"word":"meant"},{"word":"effect"}],"minWords":60,"minSentences":6,"rubric":["Task done: all three rewritten with S, B and I","Organised: same order each time","Language: past simple with a time; this meant / the effect was","Tone: no labels or personality words"],"rubricI18n":{"tr":["Görev: üçü de S, B ve I ile yeniden yazılmış","Düzen: her seferinde aynı sıra","Dil: zaman belirten past simple; this meant / the effect was","Üslup: etiket ya da kişilik sözcüğü yok"],"fa":["کامل بودن کار: هر سه مورد با S، B و I بازنویسی شده‌اند","نظم: هر بار همان ترتیب","زبان: گذشته‌ی ساده همراه با زمان؛ this meant / the effect was","لحن: بدون برچسب زدن و بدون کلمه‌هایی درباره‌ی شخصیت"]},"portfolio":null,"parts":[{"t":{"en":"The situation, with a time","tr":"Zamanıyla birlikte durum","fa":"موقعیت، همراه با زمان"},"find":["on 14 july","on tuesday","on 2 august","when"],"sample":"On 14 July, at the Al Noor clinic"},{"t":{"en":"The behaviour","tr":"Davranış","fa":"رفتار"},"find":["you said","was not signed","you called"],"sample":"the delivery note was not signed"},{"t":{"en":"The impact","tr":"Etkisi","fa":"اثرش"},"find":["this meant","the effect was"],"sample":"we waited nine days for payment"}]},"perspective":{"id":"c-hr-5-2-p","title":{"en":"Deniz reads two kinds of feedback","tr":"Deniz iki tür geri bildirimi okuyor","fa":"دنیز دو جور بازخورد را می‌خواند"},"course":"hr","unit":"hr-5-2","type":"perspective","minSentences":2,"prompt":{"en":"You are Deniz. You read \"Careless with paperwork\" first, then Leyla's version. Write 2-3 sentences in first person: how did each one feel, and which would you act on?","tr":"Deniz'sin. Önce \"Careless with paperwork\" cümlesini, sonra Leyla'nın versiyonunu okudun. Birinci tekil şahısla 2-3 cümle yaz: her biri nasıl hissettirdi ve hangisine göre harekete geçerdin?","fa":"تو دنیز هستی. اول جمله‌ی «Careless with paperwork» را خواندی و بعد نسخه‌ی لیلا را. از زبان خودت دو یا سه جمله بنویس: هر کدام چه حسی به تو داد، و بر اساس کدام‌یک واقعاً کاری می‌کردی؟"}},"exit":{"id":"c-hr-5-2-x","course":"hr","unit":"hr-5-2","type":"exit","items":[{"from":"hr-5-2","kind":"blank","prompt":"Last Tuesday the van ___ left unlocked.","options":["is","was","has"],"correct":1,"point":2,"why":{"en":"was: a finished event last Tuesday, and the van received the action: was + past participle. 'Is' is the present, and 'has left' doesn't fit last Tuesday.","tr":"was: geçen salı bitmiş bir olay ve minibüs eylemi aldı: was + üçüncü hâl. 'Is' şimdiki zamandır; 'has left' last Tuesday ile uymaz.","fa":"was درست است، چون اتفاق سه‌شنبه‌ی گذشته تمام شده و ون باز گذاشته شده: was و اسم مفعول. is زمان حال است و has با last Tuesday جور نیست."}},{"from":"hr-5-2","kind":"blank","prompt":"As a result, we ___ two hours on the claim.","options":["lost","lose","losing"],"correct":0,"point":2,"why":{"en":"lost: the impact of a past event takes the past simple. 'Lose' is the present, and 'losing' is not a full verb.","tr":"lost: geçmiş bir olayın etkisi past simple alır. 'Lose' şimdiki zamandır; 'losing' tam fiil değildir.","fa":"lost درست است، چون اثر یک اتفاق گذشته گذشته‌ی ساده می‌خواهد. lose زمان حال است و losing فعل کامل نیست."}},{"from":"hr-5-2","kind":"mcq","prompt":"Which feedback has a situation, a behaviour and an impact?","options":["You are careless.","Great job last week!","On Tuesday you sent the report late, so the client meeting was moved."],"correct":2,"point":1,"why":{"en":"It names the situation (Tuesday), the behaviour (sent late) and the impact (meeting moved). 'You are careless' judges the person, and 'Great job!' gives no detail.","tr":"Durumu (salı), davranışı (geç gönderildi) ve etkiyi (toplantı ertelendi) söyler. 'You are careless' kişiyi yargılar; 'Great job!' ayrıntı vermez.","fa":"موقعیت (سه‌شنبه)، رفتار (دیر فرستادن) و اثر (عقب افتادن جلسه) را می‌گوید. You are careless آدم را قضاوت می‌کند و Great job! جزئیاتی ندارد."}},{"from":"hr-5-1","kind":"blank","prompt":"Check every note twice ___ avoid lost payments.","options":["to","for","for to"],"correct":0,"point":2,"why":{"en":"to: to + verb gives the purpose. 'For' + verb is wrong for purpose, and 'for to' is not English.","tr":"to: to + fiil amacı verir. Amaç için 'for' + fiil yanlıştır; 'for to' İngilizce değildir.","fa":"to درست است، چون to و فعل هدف را می‌گوید. for با فعل برای هدف غلط است و for to انگلیسی نیست."},"hint2":{"en":"The gap gives a purpose, and a base verb (avoid) follows it. Which option works before a verb?","tr":"Boşluk bir amaç veriyor ve ardından yalın bir fiil (avoid) geliyor. Hangi seçenek bir fiilden önce kullanılır?","fa":"جای خالی هدف را می‌گوید و بعدش یک فعل ساده (⁨avoid⁩) آمده. کدام گزینه قبل از فعل می‌آید؟"}},{"from":"hr-4-3","kind":"blank","prompt":"So what you're ___ is that the team is tired.","options":["say","saying","said"],"correct":1,"point":2,"why":{"en":"saying: 'what you're saying' needs -ing after are. 'Say' and 'said' don't follow you're.","tr":"saying: 'what you're saying' are'dan sonra -ing ister. 'Say' ve 'said' you're'dan sonra gelmez.","fa":"saying درست است، چون در what you're saying بعد از are فعل ing‌دار می‌آید. say و said بعد از you're نمی‌آیند."},"hint2":{"en":"What you’re ... is is a summary phrase: be + a verb form. Which form follows you’re here?","tr":"What you’re ... is bir özetleme kalıbıdır: be + fiilin bir biçimi. Burada you’re’dan sonra hangi biçim gelir?","fa":"⁨What you’re ... is⁩ یک عبارت خلاصه‌کردن است: ⁨be⁩ با یک شکل از فعل. این‌جا بعد از ⁨you’re⁩ کدام شکل می‌آید؟"}},{"from":"hr-3-3","kind":"blank","prompt":"She gave very ___ evidence of planning skills.","options":["limited","few","many"],"correct":0,"point":2,"why":{"en":"limited: 'evidence' is uncountable, and 'very limited evidence' is the careful way to say there is little. 'Few' and 'many' need countable plurals.","tr":"limited: 'evidence' sayılamaz; 'very limited evidence' çok az kanıt olduğunu söylemenin dikkatli yoludur. 'Few' ve 'many' sayılabilen çoğul ister.","fa":"limited درست است، چون evidence شمارش‌ناپذیر است و very limited evidence شیوه‌ی محتاطانه‌ی گفتن «شاهد خیلی کم» است. few و many اسم جمعِ شمارش‌پذیر می‌خواهند."}}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
